22	// What a service or the system said, after its name, in the one form shown
23	// for another side's own words. The words stay in the language they came in.
24	inline std::string said_by(const std::string& name, const std::string& words)
25	{
26	    // TRN %1% is an AI provider or the operating system, such as OpenAI or macOS. %2% is what it answered, in its own words and language.
27	    return Slic3r::format(translated(L("%1% says: “%2%”")), name, words);
28	}
29	
30	inline const char* system_name()
31	{
32	#if defined(__APPLE__)
33	    return "macOS";
34	#elif defined(_WIN32)
35	    return "Windows";
36	#else
37	    return "Linux";
38	#endif
39	}
40	
41	// The system's words when it refused for one of those causes, or nothing.
42	// A std::filesystem error is a std::system_error, and so is what the app's
43	// own writes throw with the errno or Windows error they met. OrcaSlicer's own
44	// file code throws boost::filesystem errors, which are boost's system_error.
45	inline std::optional<std::string> refused_by_system(const std::exception& error)
46	{
47	    if (const auto* system = dynamic_cast<const std::system_error*>(&error)) {
48	        const std::error_condition condition = system->code().default_error_condition();
49	        if (condition != std::errc::no_space_on_device && condition != std::errc::permission_denied &&
50	            condition != std::errc::read_only_file_system && condition != std::errc::operation_not_permitted)
51	            return std::nullopt;
52	        return system->code().message();
53	    }
54	    if (const auto* system = dynamic_cast<const boost::system::system_error*>(&error)) {
55	        namespace errc = boost::system::errc;
56	        const boost::system::error_condition condition = system->code().default_error_condition();
57	        if (condition != errc::no_space_on_device && condition != errc::permission_denied &&
58	            condition != errc::read_only_file_system && condition != errc::operation_not_permitted)
59	            return std::nullopt;
60	        return system->code().message();
61	    }
62	    return std::nullopt;
63	}
