bool project_edit(WorkspaceChangeReasons reasons)
{
    return has_reason(reasons, WorkspaceChangeReasons::Project) ||
           has_reason(reasons, WorkspaceChangeReasons::Contents) ||
           has_reason(reasons, WorkspaceChangeReasons::Transform) ||
           has_reason(reasons, WorkspaceChangeReasons::Plates) ||
           has_reason(reasons, WorkspaceChangeReasons::Settings) ||
           has_reason(reasons, WorkspaceChangeReasons::History);
}

// The folders in the projects folder, or nothing when that folder exists but
// cannot be listed (its permissions, a storage fault): callers say so rather
// than treat it as holding no projects. No projects folder yet is a new
// installation with none.
std::vector<std::filesystem::path> project_folders(const std::filesystem::path& root, std::error_code& error)
{
    std::vector<std::filesystem::path> folders;
    // exists() clears the error for a path that is not there; is_directory()
    // reports it as an error.
    if (!std::filesystem::exists(root, error) && !error)
        return folders;
    std::filesystem::directory_iterator it(root, error);
    for (const std::filesystem::directory_iterator end; !error && it != end; it.increment(error))
        folders.push_back(it->path());
    return folders;
}

// A project has a card once it has held a model, whatever it holds now: a
// person who deleted every object can still go back to an earlier version.
void ProjectAutosave::tick()
{
    m_unexpected = nullptr;
    m_persistence.resolve_pending_boundary();
    if (stopped())
        return;
    if (m_cleanup_failure)
        std::rethrow_exception(std::exchange(m_cleanup_failure, nullptr));
    try {
        adopt_project();
        if (!settle(false) && m_worker.valid())
            return;
        observe_document_change();
        const auto now = Clock::now();
        if (now < m_next_probe)
            return;
        m_next_probe = now + kProbeInterval;
        if (blank()) {
            m_state = State::Saved;
            return;
        }
        const std::string model_input = observed_input();
        if (model_input != m_seen_model_input) {
            m_seen_model_input = model_input;
            m_last_edit = now;
            m_state = State::Saving;
        }
        const bool document_pending = m_persistence.document().doc_revision() != m_committed_semantic_revision;
        const bool document_due = document_pending &&
            (now - m_last_semantic_edit >= kEditQuietPeriod ||
             (m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay));
        // A continuously edited model must not starve the current document.
        // Model capture also publishes the document, so a ready model still
        // takes precedence until the document's maximum delay is reached.
        if (document_due && m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay) {
            persist_document(false);
            return;
        }
        const bool model_pending = m_store->head_id().empty() || model_input != m_last_capture_input;
        const bool held          = model_pending && m_capture_hold && m_capture_hold();
        if (model_pending && !held) {
            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
            if (canvas == nullptr || !canvas->is_initialized() ||
                canvas->get_gizmos_manager().is_in_editing_mode(true) ||
                now - m_last_edit < kEditQuietPeriod)
                return;
            capture(false);
        } else if (document_pending) {
            if (!document_due)
                return;
            persist_document(false);
        } else if (!held) {
            m_state = State::Saved;
            m_first_semantic_edit.reset();
        }
    } catch (const std::exception& error) {
        fail(error);
    }
    // A failure the person can fix keeps the project trying, so it saves once
    // they free space or fix the folder. One of ours stops this project's
    // saving for the run and goes up to the timer's report, once.
    if (m_unexpected) {
        m_stopped_project = m_persistence.document().project_id();
        std::rethrow_exception(std::exchange(m_unexpected, nullptr));
    }
}

