+// JusPrin's process is alive (the discovery record names it) but what holds
+// its port answers with something other than MCP, or not in time: JusPrin is
+// open, so telling the client to open it sends the person to fix what is ours.
+// Nothing listening on the port is still JusPrin not being open.
+TEST_CASE("MCP bridge tells a client JusPrin is open when JusPrin's answer is broken", "[mcp][bridge]")
+{
+    namespace net = boost::asio;
+    const int scenario = GENERATE(0, 1, 2); // not MCP, no answer, nothing listening
+    net::io_context io;
+    net::ip::tcp::acceptor acceptor(io, {net::ip::make_address_v4("127.0.0.1"), 0});
+    const unsigned short port = acceptor.local_endpoint().port();
+    if (scenario == 2) acceptor.close();
+    std::thread listener([&] {
+        if (scenario == 2) return;
+        net::ip::tcp::socket socket(io);
+        boost::system::error_code error;
+        acceptor.accept(socket, error);
+        if (error) return;
+        if (scenario == 0) {
+            const std::string page = "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: 2\r\n\r\nhi";
+            net::write(socket, net::buffer(page), error);
+        } else std::this_thread::sleep_for(std::chrono::milliseconds(400));
+    });
+    Harness h;
+    Mcp::write_discovery(h.directory.path(), "http://127.0.0.1:" + std::to_string(port) + "/mcp");
+    auto request = JusPrinTest::request("tools/call", {{"name", "workspace_inspect"}}); request["id"] = 1; h.send(request);
+    const auto result = h.wait(1)["result"];
+    listener.join();
+    CHECK(result["isError"] == true);
+    CHECK(result["structuredContent"]["error"]["code"] == (scenario == 2 ? "workspace_unavailable" : "failed"));
+}

